    {
      "card_ids": ["C06"],
      "claim": "Oleic acid, a long-chain fatty acid, shows high brain uptake and has been proposed as a PET tracer for cerebral fatty-acid metabolism, demonstrating meaningful BBB permeability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Radiolabeled palmitate crosses the human BBB after intravenous injection and is incorporated into brain tissue, providing direct human evidence for CNS access of long-chain lipids.",
